package edu.pe.cibertec.saibm.membresia.infrastructure.messaging;
import org.springframework.amqp.core.*; import org.springframework.amqp.support.converter.Jackson2JsonMessageConverter; import org.springframework.context.annotation.*; import com.fasterxml.jackson.databind.ObjectMapper;
@Configuration public class MembershipRabbitConfig {public static final String EXCHANGE="saibm.membership.v1",DLQ="membership-dlq";@Bean Jackson2JsonMessageConverter membershipConverter(ObjectMapper m){return new Jackson2JsonMessageConverter(m);}@Bean TopicExchange membershipExchange(){return new TopicExchange(EXCHANGE,true,false);}@Bean Queue membershipEvents(){return QueueBuilder.durable("membership-events").deadLetterExchange(EXCHANGE).deadLetterRoutingKey(DLQ).build();}@Bean Binding membershipEventsBinding(){return BindingBuilder.bind(membershipEvents()).to(membershipExchange()).with("#");}@Bean Queue membershipDlq(){return QueueBuilder.durable(DLQ).build();}@Bean Binding membershipDlqBinding(){return BindingBuilder.bind(membershipDlq()).to(membershipExchange()).with(DLQ);}}
